export function dominates(a,b){const ks=Object.keys(a);return ks.length>0&&ks.every(k=>Number.isFinite(a[k])&&Number.isFinite(b[k])&&a[k]>=b[k])&&ks.some(k=>a[k]>b[k]);}
export function selectIdeas(ideas,f){return ideas.filter(x=>(!f.scope||x.scope===f.scope)&&(!f.intervention||x.intervention===f.intervention)&&(!f.frontier||x.nominalNicheFrontier)&&(!f.search||[x.id,x.title,x.claim,x.mechanism,x.nextTest,x.falsifier,x.confounds,...x.aliases].join(' ').toLowerCase().includes(f.search.toLowerCase()))).sort((a,b)=>f.sort==='id'?a.id.localeCompare(b.id):(b.scores[f.sort]-a.scores[f.sort]||a.id.localeCompare(b.id)));}
export async function mountIdeas(doc,fetcher=fetch){
 const $=id=>doc.getElementById(id),el=(tag,t,cls)=>{const x=doc.createElement(tag);if(t!==undefined)x.textContent=t;if(cls)x.className=cls;return x;};
 let data,controls,messages,audit;try{[data,controls,messages,audit]=await Promise.all(['archive.json','controls.json','messages.json','review-audit.json'].map(async f=>{const r=await fetcher('./'+f);if(!r.ok)throw Error('HTTP '+r.status);return r.json();}));}catch(e){$('load-status').textContent='Could not load the evaluation. Please reload. '+e.message;return null;}
 const byId=new Map(data.ideas.map(x=>[x.id,x])),messageMap=new Map(messages.map(x=>[x.id,x]));let chosen=data.shortlist[0].id;const state={scope:'',intervention:'',frontier:false,search:'',sort:'id'};
 const a=(text,href,download=false)=>{const x=el('a',text);x.href=href;if(download)x.setAttribute('download','');return x;};
 for(const [n,label] of [[data.summary.ideaFamilies,'canonical idea families'],[data.summary.occupiedDeclaredCells+'/16','declared cells occupied'],[data.summary.queueEligible,'bounded experiment candidates'],[controls.checks.length,'passing numerical controls']]){const x=el('div');x.append(el('strong',String(n)),el('span',label));$('stats').append(x);}
 for(const s of data.shortlist){const x=byId.get(s.id),b=el('button');b.append(el('strong',x.id+' / '+x.title),el('span',s.reason));b.addEventListener('click',()=>{chosen=x.id;renderDetails();$('details').scrollIntoView?.({behavior:'smooth',block:'start'});renderRows();});$('shortlist').append(b);}
 for(const [id,values] of [['scope',data.method.scopeOrder],['intervention',data.method.interventionOrder]])for(const v of values){const o=el('option',v);o.value=v;$(id).append(o);}
 for(const x of data.ideas){const o=el('option',x.id+' / '+x.title);o.value=x.id;$('compare').append(o);}
 for(const axis of data.method.axes){const d=el('div');d.append(el('h3',axis.name));const l=el('ol');l.setAttribute('start','0');axis.anchors.forEach(t=>l.append(el('li',t)));d.append(l);$('rubric').append(d);}
 function renderNiches(){const n=$('niches');n.replaceChildren(el('span','Scope / intervention','axis'));data.method.interventionOrder.forEach(v=>n.append(el('span',v,'axis')));for(const sc of data.method.scopeOrder){n.append(el('span',sc,'axis'));for(const it of data.method.interventionOrder){const count=data.ideas.filter(x=>x.scope===sc&&x.intervention===it).length,b=el('button',undefined,count?'':'empty');b.append(el('b',String(count)),el('span',count?'idea families':'No idea tagged'));b.setAttribute('aria-label',sc+' / '+it+': '+count+' idea families');b.setAttribute('aria-pressed',String(state.scope===sc&&state.intervention===it));b.addEventListener('click',()=>{state.scope=sc;state.intervention=it;$('scope').value=sc;$('intervention').value=it;render();});n.append(b);}}}
 function renderRows(){const rows=selectIdeas(data.ideas,state);$('result-count').textContent=rows.length+' of '+data.ideas.length+' ideas · profile order: specification / discrimination / tractability / leverage';$('rows').replaceChildren();for(const x of rows){const tr=el('tr');tr.dataset.selected=String(x.id===chosen);const td=el('td'),b=el('button',x.id+' / '+x.title);b.addEventListener('click',()=>{chosen=x.id;renderRows();renderDetails();});td.append(b,el('span',x.evidence,'evidence'));tr.append(td);for(const k of data.method.axes.map(x=>x.id)){const c=el('td'),v=el('span',String(x.scores[k])+'/4','score'),bar=el('i');bar.style.setProperty('--score',x.scores[k]);v.append(bar,el('small',x.scoreIntervals[k].join('–')+' sensitivity'));c.append(v);tr.append(c);}tr.append(el('td',x.novelty));$('rows').append(tr);}}
 function detail(x){const d=el('article',undefined,'idea-detail');d.append(el('span',x.id+' / '+x.niche,'eyebrow'),el('h3',x.title));const tags=el('div');for(const t of [x.evidence,x.novelty,'Literature novelty: unknown',x.queueEligible?'Experiment queue':'Needs specification or infrastructure',x.nominalNicheFrontier?'Nominal niche frontier':'Nominally dominated or outside queue'])tags.append(el('span',t,'pill'));d.append(tags,el('p',x.claim));const profile=el('div',undefined,'profile');for(const axis of data.method.axes){const t=el('span',axis.name);t.append(el('b',String(x.scores[axis.id])));profile.append(t);}d.append(profile,el('p',x.scoreRationale));const dl=el('dl');for(const [name,key] of [['Next discriminating test','nextTest'],['Baseline','baseline'],['What would falsify it?','falsifier'],['Confounds & hidden choices','confounds']])dl.append(el('dt',name),el('dd',x[key]));dl.append(el('dt','Ranking sensitivity'),el('dd','Nominally dominated by: '+(x.dominatedBy.join(', ')||'none in this niche')+'. Robustly dominated under ±1 bands: '+(x.robustlyDominatedBy.join(', ')||'none')+'. These labels do not decide which scientific function to preserve.'));d.append(dl,el('blockquote',x.source.quote),el('p','Exact source: '+x.source.messageId+' · characters '+x.source.start+'–'+x.source.end,'source-meta'));const source=el('details'),summary=el('summary','Read the complete source message');source.append(summary,el('pre',messageMap.get(x.source.messageId)?.text||'Source unavailable'));d.append(source);if(x.aliases.length)d.append(el('p','Merged aliases / facets: '+x.aliases.join(' · '),'small'));return d;}
 function renderDetails(){$('details').replaceChildren(detail(byId.get(chosen)));const other=$('compare').value;if(other&&other!==chosen)$('details').append(detail(byId.get(other)));}
 function render(){renderNiches();renderRows();renderDetails();}
 for(const id of ['scope','intervention','sort'])$(id).addEventListener('change',()=>{state[id]=$(id).value;render();});$('search').addEventListener('input',()=>{state.search=$('search').value;renderRows();});$('frontier').addEventListener('change',()=>{state.frontier=$('frontier').checked;renderRows();});$('compare').addEventListener('change',renderDetails);$('reset').addEventListener('click',()=>{Object.assign(state,{scope:'',intervention:'',frontier:false,search:'',sort:'id'});for(const id of ['scope','intervention','search'])$(id).value='';$('sort').value='id';$('frontier').checked=false;render();});
 const cards=[['Fixed-port isospectral routing','100% → opposite output','At E=0, γ=2, ±π/2 flux routes the input to opposite labelled ports with identical eigenvalues. Allowing output swaps makes this symmetric pair equivalent.'],['Same eigenvalues, different gain',controls.nonnormal.rows[1].maxAmplitudeGainOnGrid.toFixed(3)+'× amplitude','Two stable 2×2 matrices share eigenvalues −1, −2. Off-diagonal 8 gives transient amplification; the normal comparator peaks at 1. Grid maximum only; not useful-computation proof.'],['Same local derivative, different basin','0 versus 1','Both nonlinear examples have derivative −1 at zero. Starting at x=.9, one decays to zero and the other approaches one. This is not yet a write/read memory demonstration.'],['Restricted measurement alias','Same observed response','diag(0,1) and diag(0,2), with input/output only on the first coordinate, give equal tested responses despite different unobserved spectra. More observation can break an apparent equivalence.'],['A diversity proxy fails','5 for 6 identical agents','Positive-Laplacian spectral entropy gives effective count 5 on a complete graph even when every agent representation is identical. It cannot certify representation diversity.']];for(const [title,note,body] of cards){const c=el('article');c.append(el('h3',title),el('div',note,'number'),el('p',body));$('controls').append(c);}
 for(const rule of [0,204,43,94,54]){const x=controls.eca.rows.find(x=>x.rule===rule),tr=el('tr');for(const v of [rule,x.distinctFunctions,x.distinctBijectiveFunctions,x.meanInputOutputInformationBits.toFixed(3)+' bits'])tr.append(el('td',String(v)));$('eca').append(tr);}
 for(const x of data.corrections){const d=el('article');d.append(el('h3',x.claim),el('p',x.correction));$('corrections').append(d);}
 for(const x of audit.reviewers){const d=el('article');d.append(el('h3',x.role),el('p',x.method),el('p',x.overlap,'small'),a('Read frozen first pass ↓','./'+x.file,true));$('reviewers').append(d);}
 for(const t of data.limitations)$('limits').append(el('li',t));for(const r of data.references){const p=el('p');p.append(a(r.title+' ↗',r.url),el('span',' — '+r.checkedScope));$('references').append(p);}
 $('load-status').textContent='Evaluation loaded · source spans and numerical checks verified';$('content').hidden=false;render();return {data,state,select:id=>{if(!byId.has(id))throw Error('Unknown idea');chosen=id;render();}};
}
if(typeof document!=='undefined')mountIdeas(document);
